<?php
require_once "inc/config.php"; require_once "inc/admin_auth.php"; require_admin_permission($pdo,'customers');
$id=(int)($_GET['id']??0);
$stmt=$pdo->prepare("SELECT * FROM customers WHERE id=? LIMIT 1"); $stmt->execute([$id]); $customer=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$customer){http_response_code(404);exit('Müştəri tapılmadı.');}
$stmt=$pdo->prepare("SELECT id,name,is_active FROM markets WHERE customer_id=? ORDER BY id DESC");$stmt->execute([$id]);$markets=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare("SELECT id,title,status,price,currency,created_at FROM listings WHERE customer_id=? ORDER BY id DESC LIMIT 50");$stmt->execute([$id]);$listings=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare("SELECT id,title,status,start_date,end_date FROM tenders WHERE customer_id=? ORDER BY id DESC LIMIT 50");$stmt->execute([$id]);$tenders=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare("SELECT id,provider,amount,currency,status,created_at FROM payments WHERE cust_id=? ORDER BY id DESC LIMIT 50");$stmt->execute([$id]);$payments=$stmt->fetchAll(PDO::FETCH_ASSOC);
$stmt=$pdo->prepare("SELECT s.id,s.status,s.starts_at,s.ends_at,s.price_paid,s.currency,p.name package_name FROM customer_subs s LEFT JOIN packages p ON p.id=s.package_id WHERE s.cust_id=? ORDER BY s.id DESC LIMIT 20");$stmt->execute([$id]);$subs=$stmt->fetchAll(PDO::FETCH_ASSOC);
function row_badge(string $s): string { return '<span class="badge '.($s==='active'||$s==='paid'?'bg-success':($s==='blocked'||$s==='failed'?'bg-danger':'bg-warning')).'">'.admin_h($s).'</span>'; }
?>
<!doctype html><html lang="az"><head><?php include "inc/head.php"; ?></head><body><div class="app-main"><div id="app-wrapper" class="app-wrapper d-flex flex-column align-items-stretch min-vh-100"><?php include "inc/sidebar.php"; ?><?php include "inc/navbar.php"; ?><div class="app-content-wrapper py-13"><div class="container-fluid"><div class="page-header pb-7"><h2 class="fw-semibold fs-7"><?=admin_h($customer['full_name'])?></h2><div class="text-muted">#<?=$customer['id']?> · <?=admin_h($customer['type'])?> · <?=row_badge($customer['status'])?></div></div><div class="row g-4"><div class="col-xl-4"><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body"><h5>Profil</h5><p><b>Email:</b> <?=admin_h($customer['email'])?></p><p><b>Telefon:</b> <?=admin_h($customer['phone'])?></p><p><b>Email:</b> <?=((int)$customer['email_verified']?'Doğrulanıb':'Doğrulanmayıb')?></p><p><b>Telefon:</b> <?=((int)$customer['phone_verified']?'Doğrulanıb':'Doğrulanmayıb')?></p><p><b>Qeydiyyat:</b> <?=admin_h($customer['created_at'])?></p></div></div></div><div class="col-xl-8"><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body"><h5>Marketlər</h5><table class="table"><?php foreach($markets as $m):?><tr><td>#<?=$m['id']?></td><td><?=admin_h($m['name'])?></td><td><?=((int)$m['is_active']?'Aktiv':'Deaktiv')?></td></tr><?php endforeach;?></table></div></div></div><div class="col-12"><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body"><h5>Elanlar</h5><table class="table"><tr><th>ID</th><th>Başlıq</th><th>Status</th><th>Qiymət</th><th>Tarix</th></tr><?php foreach($listings as $x):?><tr><td>#<?=$x['id']?></td><td><?=admin_h($x['title'])?></td><td><?=row_badge($x['status'])?></td><td><?=admin_h($x['price'].' '.$x['currency'])?></td><td><?=admin_h($x['created_at'])?></td></tr><?php endforeach;?></table></div></div></div><div class="col-xl-6"><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body"><h5>Tenderlər</h5><table class="table"><?php foreach($tenders as $x):?><tr><td>#<?=$x['id']?></td><td><?=admin_h($x['title'])?></td><td><?=row_badge($x['status'])?></td></tr><?php endforeach;?></table></div></div></div><div class="col-xl-6"><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body"><h5>Abunəliklər</h5><table class="table"><?php foreach($subs as $x):?><tr><td>#<?=$x['id']?></td><td><?=admin_h($x['package_name']??'-')?></td><td><?=row_badge($x['status'])?></td><td><?=admin_h($x['price_paid'].' '.$x['currency'])?></td></tr><?php endforeach;?></table></div></div></div><div class="col-12"><div class="pure-card card-bg shadow-custom rounded-custom"><div class="pure-card-body"><h5>Ödənişlər</h5><table class="table"><tr><th>ID</th><th>Provider</th><th>Məbləğ</th><th>Status</th><th>Tarix</th></tr><?php foreach($payments as $x):?><tr><td>#<?=$x['id']?></td><td><?=admin_h($x['provider'])?></td><td><?=admin_h($x['amount'].' '.$x['currency'])?></td><td><?=row_badge($x['status'])?></td><td><?=admin_h($x['created_at'])?></td></tr><?php endforeach;?></table></div></div></div></div></div></div><?php include "inc/footer.php"; ?></div></div><?php include "inc/scripts_url.php"; ?></body></html>
